import { Severity } from "../language-server/types";

export type PLICode = SimplePLICode | ParametricPLICode;

/**
 * Used for non-parametric PLI compiler codes/messages
 */
export interface SimplePLICode {
  /**
   * The IBM code itself, without severity, ex. 'IBM1018I'
   */
  code: string;

  /**
   * Code severity, one of 'I', 'W', 'E', 'S', 'U', comes after the code itself
   */
  severity: Severity;

  /**
   * Human readable message for the code
   */
  message: string;
}

/**
 * Used for parametric PLI compiler codes/messages
 */
export interface ParametricPLICode {
  /**
   * The IBM code itself, without severity, ex. 'IBM1018I'
   */
  code: string;

  /**
   * Code severity, one of 'I', 'W', 'E', 'S', 'U', comes after the code itself
   */
  severity: Severity;

  /**
   * Message for the code, with placeholders for parameters
   */
  message: (...args: any[]) => string;
}

export function isPLICode(code: unknown): code is PLICode {
  return (
    typeof code === "object" &&
    code !== null &&
    "code" in code &&
    "severity" in code &&
    "message" in code
  );
}

export function isParametricPLICode(code: unknown): code is ParametricPLICode {
  return isPLICode(code) && typeof code.message === "function";
}

export function isSimplePLICode(code: unknown): code is SimplePLICode {
  return isPLICode(code) && typeof code.message === "string";
}

